describe('Locked Out User Login Error Message', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should display locked out error message when attempting to log in with locked user', () => {
    cy.get('[data-testid="user-input"]').type('locked_out_user');
    cy.get('[data-testid="password-input"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();

    cy.get('[data-testid="error"]')
      .should('be.visible')
      .should('contain', 'Sorry, this user has been locked out');

    cy.get('[data-testid="error"]')
      .should('have.class', 'error-message');

    cy.get('[data-testid="error"]')
      .should('be.visible');

    cy.get('[data-testid="login-button"]')
      .should('be.visible');
  });

  it('should not navigate to inventory page when locked out user attempts login', () => {
    cy.get('[data-testid="user-input"]').type('locked_out_user');
    cy.get('[data-testid="password-input"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();

    cy.get('[data-testid="error"]')
      .should('be.visible')
      .should('contain', 'Sorry, this user has been locked out');

    cy.url().should('include', '/login');
    cy.get('[data-testid="inventory-page"]')
      .should('not.exist');
  });
});
